mapper.select:
UPDATE membership SET status = #{to}, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{actor}
WHERE tenant_id = #{tenantId} AND id = #{membershipId} AND status = #{from} AND NOT deleted
RETURNING tenant_id, version

SELECT m.id AS membership_id, i.account, i.display_name, i.email, i.phone, m.status

ORDER BY m.id
LIMIT #{limit} OFFSET #{offset}

UPDATE membership SET attributes = attributes - #{code}, updated_at = CURRENT_TIMESTAMP, updated_by = #{actor}
WHERE tenant_id = #{tenantId} AND attributes ?? #{code} AND NOT deleted
RETURNING id
